<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import type { ColDef } from 'ag-grid-community'
import { ElMessage, ElMessageBox } from 'element-plus'
import AppDataGrid from '@/components/AppDataGrid.vue'
import { deleteCertificate, getCertificate, listCertificates, listDNSProviders, renewCertificate, saveCertificate, type SSLCertificate, type SSLCertificateForm, type SSLDNSProvider } from '@/api/ssl-cert'
import { useAuthStore } from '@/stores/auth'
const auth=useAuthStore(),rows=ref<SSLCertificate[]>([]),providers=ref<SSLDNSProvider[]>([]),keyword=ref(''),status=ref(''),sourceType=ref(''),page=ref(1),pageSize=ref(20),total=ref(0),loading=ref(false),dialog=ref(false)
const empty=():SSLCertificateForm=>({name:'',domain:'',san_domains:'',acme_email:'',ca_provider:'letsencrypt',key_algorithm:'rsa2048',source_type:'manual',cloud_account_id:0,dns_provider_id:0,certificate:'',private_key:'',cert_chain:'',auto_renew:true,renew_days_before:30});const form=reactive<SSLCertificateForm>(empty())
async function load(){loading.value=true;try{const {data}=await listCertificates({keyword:keyword.value,status:status.value,source_type:sourceType.value,page:page.value,limit:pageSize.value});rows.value=data.data.list;total.value=data.data.total}finally{loading.value=false}}
async function open(row?:SSLCertificate){Object.assign(form,empty());if(row){const {data}=await getCertificate(row.id);Object.assign(form,data.data)}dialog.value=true}
async function save(){if(!form.name.trim()||!form.domain.trim())return ElMessage.warning('请填写证书名称和域名');await saveCertificate(form);dialog.value=false;ElMessage.success('保存成功');await load()}
async function remove(row:SSLCertificate,confirm=true){if(confirm)await ElMessageBox.confirm(`确认删除证书“${row.name}”吗？`,'删除确认',{type:'warning'});await deleteCertificate(row.id)}
async function bulkDelete(selected:unknown[]){const items=selected as SSLCertificate[];await ElMessageBox.confirm(`确认删除选中的 ${items.length} 个证书吗？`,'批量删除',{type:'warning'});for(const item of items)await remove(item,false);await load()}
async function renew(row:SSLCertificate){await renewCertificate(row.id);ElMessage.success('续期任务已创建')}
function actions(p:{data:SSLCertificate}){const w=document.createElement('div');w.className='ssl-actions';const add=(text:string,cls:string,fn:()=>void)=>{const b=document.createElement('button');b.textContent=text;b.className=cls;b.onclick=fn;w.append(b)};if(auth.hasPermission('POST /api/v1/ssl-cert/certificates/renew'))add('续期','ssl-link',()=>void renew(p.data));if(auth.hasPermission('POST /api/v1/ssl-cert/certificates/save'))add('编辑','ssl-edit',()=>void open(p.data));if(auth.hasPermission('POST /api/v1/ssl-cert/certificates/delete'))add('删除','ssl-delete',()=>void remove(p.data).then(load));return w}
const columns=computed<ColDef[]>(()=>[{headerName:'序号',width:64,valueGetter:p=>(page.value-1)*pageSize.value+(p.node?.rowIndex||0)+1},{field:'name',headerName:'证书名称',minWidth:140},{field:'domain',headerName:'域名',minWidth:170},{field:'source_type',headerName:'来源',width:90,valueFormatter:p=>({manual:'手动导入',acme:'ACME',aliyun:'阿里云'}[p.value as string]||p.value)},{field:'ca_provider',headerName:'CA',width:100},{field:'status',headerName:'状态',width:90},{field:'not_after',headerName:'到期时间',minWidth:145,valueFormatter:p=>p.value?String(p.value).replace('T',' ').slice(0,19):'-'},{headerName:'操作',pinned:'right',width:220,cellRenderer:actions}])
watch([keyword,status,sourceType],()=>{page.value=1;void load()});onMounted(async()=>{await load();const {data}=await listDNSProviders({keyword:'',provider:'',page:1,limit:1000});providers.value=data.data.list})
</script>
<template><section class="ssl-page"><header><div><h2>证书管理</h2><p>管理证书申请、导入、续期和有效期。</p></div></header><div class="toolbar"><div class="filters"><el-input v-model="keyword" placeholder="搜索证书或域名" clearable/><el-select v-model="sourceType" placeholder="选择证书来源" clearable><el-option label="手动导入" value="manual"/><el-option label="ACME" value="acme"/><el-option label="阿里云" value="aliyun"/></el-select><el-select v-model="status" placeholder="选择状态" clearable><el-option label="待处理" value="pending"/><el-option label="有效" value="active"/><el-option label="即将到期" value="expiring"/><el-option label="已过期" value="expired"/><el-option label="错误" value="error"/></el-select></div><el-button v-permission="'POST /api/v1/ssl-cert/certificates/save'" type="primary" @click="open()">新增证书</el-button></div><AppDataGrid v-loading="loading" class="grid" :row-data="rows" :column-defs="columns" pagination server-pagination :total="total" :current-page="page" :page-size="pageSize" :bulk-delete="auth.hasPermission('POST /api/v1/ssl-cert/certificates/delete')?bulkDelete:undefined" @page-change="v=>{page=v;void load()}" @page-size-change="v=>{pageSize=v;page=1;void load()}"/>
<el-dialog v-model="dialog" :title="form.id?'编辑证书':'新增证书'" width="760px" destroy-on-close><el-form label-width="90px"><div class="form-row"><el-form-item label="证书名称" required><el-input v-model="form.name"/></el-form-item><el-form-item label="主域名" required><el-input v-model="form.domain"/></el-form-item></div><el-form-item label="SAN 域名"><el-input v-model="form.san_domains" placeholder="多个域名用逗号分隔"/></el-form-item><div class="form-row"><el-form-item label="证书来源"><el-select v-model="form.source_type"><el-option label="手动导入" value="manual"/><el-option label="ACME" value="acme"/><el-option label="阿里云" value="aliyun"/></el-select></el-form-item><el-form-item label="CA 提供商"><el-select v-model="form.ca_provider"><el-option label="Let's Encrypt" value="letsencrypt"/><el-option label="ZeroSSL" value="zerossl"/><el-option label="Google" value="google"/><el-option label="Buypass" value="buypass"/></el-select></el-form-item></div><div class="form-row"><el-form-item label="密钥算法"><el-select v-model="form.key_algorithm"><el-option label="RSA 2048" value="rsa2048"/><el-option label="RSA 4096" value="rsa4096"/><el-option label="EC 256" value="ec256"/></el-select></el-form-item><el-form-item label="DNS 配置"><el-select v-model="form.dns_provider_id" clearable><el-option v-for="item in providers" :key="item.id" :label="item.name" :value="item.id"/></el-select></el-form-item></div><div class="form-row"><el-form-item label="ACME 邮箱"><el-input v-model="form.acme_email"/></el-form-item><el-form-item label="提前续期"><el-input-number v-model="form.renew_days_before" :min="1" :max="90"/><span class="unit">天</span></el-form-item></div><el-form-item label="自动续期"><el-switch v-model="form.auto_renew"/></el-form-item><template v-if="form.source_type==='manual'"><el-form-item label="证书 PEM"><el-input v-model="form.certificate" type="textarea" :rows="5"/></el-form-item><el-form-item label="私钥 PEM"><el-input v-model="form.private_key" type="textarea" :rows="5"/></el-form-item><el-form-item label="证书链"><el-input v-model="form.cert_chain" type="textarea" :rows="3"/></el-form-item></template></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></section></template>
<style scoped>.ssl-page{height:100%;display:flex;flex-direction:column;gap:8px;min-width:0;padding:0 4px;font-size:11px}header h2{margin:0;font-size:20px}header p{margin:3px 0 0;color:var(--text-soft)}.toolbar{display:flex;justify-content:space-between;gap:8px}.filters{display:flex;gap:6px}.filters .el-input{width:170px}.filters .el-select{width:130px}.grid{flex:1;min-height:0}.form-row{display:grid;grid-template-columns:1fr 1fr;gap:10px}.form-row .el-select{width:100%}.unit{margin-left:5px}:deep(.ssl-actions){height:100%;display:flex;align-items:center;gap:5px}:deep(.ssl-actions button){height:26px;border-radius:8px;padding:3px 8px;background:#fff;cursor:pointer}:deep(.ssl-edit){border:1px solid var(--primary);color:var(--primary)}:deep(.ssl-link){border:1px solid #7bcf91;color:#27ae60}:deep(.ssl-delete){border:1px solid #f3b4b4;color:var(--danger)}@media(max-width:760px){.form-row{grid-template-columns:1fr}.toolbar{flex-wrap:wrap}}</style>
